    details_fetched_at timestamp(6) without time zone,
    iban character varying,
    manual boolean DEFAULT false NOT NULL,
    manual_owner_id bigint,
    name character varying,
    product character varying,
    raw_account_resource jsonb,
    raw_balances text,
    raw_details jsonb,
    status character varying DEFAULT 'active'::character varying NOT NULL,
    tpp_credential_id bigint,
    transactions_synced_at timestamp(6) without time zone,
    uid character varying NOT NULL,
    updated_at timestamp(6) without time zone NOT NULL,
    usage character varying,
    CONSTRAINT bank_accounts_ownership_xor CHECK ((((manual = true) AND (tpp_credential_id IS NULL) AND (manual_owner_id IS NOT NULL)) OR ((manual = false) AND (tpp_credential_id IS NOT NULL) AND (manual_owner_id IS NULL))))
);

