CREATE VIEW public.ledger_entries AS
 SELECT 'BankTransaction'::text AS source_type,
    bt.id AS source_id,
    bt.bank_account_id,
    bt.amount_cents,
    bt.currency,
    bt.direction,
        CASE bt.direction
            WHEN 'credit'::text THEN bt.amount_cents
            ELSE (- bt.amount_cents)
        END AS signed_amount_cents,
    bt.status,
    bt.booking_date,
    bt.transaction_date,
    bt.payment_method,
    bt.title,
    bt.counterparty_name,
    bt.counterparty_kind,
    te.id AS enrichment_id,
    te.merchant_id,
    COALESCE(te.category_id, m.default_category_id) AS effective_category_id,
    c.path AS category_path,
    COALESCE(c.essential, false) AS essential,
    te.source AS enrichment_source
   FROM (((public.bank_transactions bt
     LEFT JOIN public.transaction_enrichments te ON ((((te.enrichable_type)::text = 'BankTransaction'::text) AND (te.enrichable_id = bt.id))))
     LEFT JOIN public.merchants m ON ((m.id = te.merchant_id)))
     LEFT JOIN public.categories c ON ((c.id = COALESCE(te.category_id, m.default_category_id))))
UNION ALL
 SELECT 'ManualTransaction'::text AS source_type,
    mt.id AS source_id,
    mt.bank_account_id,
    mt.amount_cents,
    mt.currency,
    mt.direction,
        CASE mt.direction
            WHEN 'credit'::text THEN mt.amount_cents
            ELSE (- mt.amount_cents)
        END AS signed_amount_cents,
    mt.status,
    mt.booking_date,
    mt.transaction_date,
    mt.payment_method,
    mt.title,
    mt.counterparty_name,
    mt.counterparty_kind,
    te.id AS enrichment_id,
    te.merchant_id,
    COALESCE(te.category_id, m.default_category_id) AS effective_category_id,
    c.path AS category_path,
    COALESCE(c.essential, false) AS essential,
    te.source AS enrichment_source
   FROM (((public.manual_transactions mt
     LEFT JOIN public.transaction_enrichments te ON ((((te.enrichable_type)::text = 'ManualTransaction'::text) AND (te.enrichable_id = mt.id))))
     LEFT JOIN public.merchants m ON ((m.id = te.merchant_id)))
     LEFT JOIN public.categories c ON ((c.id = COALESCE(te.category_id, m.default_category_id))));

